def require(value, code):
    if not value: raise ValueError(code)


def sha(data): return hashlib.sha256(data).hexdigest()


def strict(data):
    def pairs(rows):
        result = {}
        for k, v in rows:
            require(k not in result, 'JSON_DUPLICATE'); result[k] = v
        return result
    return json.loads(data, object_pairs_hook=pairs, parse_constant=lambda _: require(False, 'JSON_NONFINITE'))


def check_time(end, reserve=0):
    require(type(end) in (int, float) and math.isfinite(end) and time.monotonic()+reserve < end, 'DEADLINE')


def read(path, limit, end):
    """Bind no-follow ordinary inode before any readable leaf open."""
    check_time(end); path = Path(path)
    require(path.is_absolute() and path.name not in ('','.','..') and '..' not in path.parts, 'FILE_PATH')
    parent=os.open('/',os.O_PATH|os.O_DIRECTORY)
    try:
        for component in path.parts[1:-1]:
            check_time(end);fd=os.open(component,os.O_PATH|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=parent)
            os.close(parent);parent=fd
        held = os.open(path.name, os.O_PATH | os.O_NOFOLLOW,dir_fd=parent)
    finally:os.close(parent)
    try:
        before = os.fstat(held)
        require(stat.S_ISREG(before.st_mode) and before.st_nlink == 1 and not before.st_mode & 0o022 and
                0 <= before.st_size <= limit, 'FILE_SHAPE')
        fd = os.open('/proc/self/fd/'+str(held), os.O_RDONLY | os.O_NONBLOCK)
        try:
            identity=lambda s:(s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_uid,s.st_gid,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
            require(identity(os.fstat(fd)) == identity(before), 'FILE_IDENTITY')
            data = bytearray()
            while block := os.read(fd, min(65536, limit+1-len(data))):
                check_time(end); data.extend(block); require(len(data)<=limit, 'FILE_CAP')
            require(identity(os.fstat(fd)) == identity(before) and identity(path.lstat()) == identity(before) and len(data)==before.st_size, 'FILE_DRIFT')
        finally: os.close(fd)
    finally: os.close(held)
    check_time(end); return bytes(data)


def source_blobs(selection, source, end):
    require(type(selection['sources']) is dict and set(selection['sources']) == set(SOURCE_PATHS), 'SOURCE_SET')
    result = {}
    for name in SOURCE_PATHS:
        row=selection['sources'][name]
        require(type(row) is dict and set(row)=={'size','sha256'} and type(row['size']) is int and
                0<row['size']<=128*1024 and type(row['sha256']) is str and len(row['sha256'])==64, 'SOURCE_ROW')
        b=read(source/name,128*1024,end);require(len(b)==row['size'] and sha(b)==row['sha256'], 'SOURCE_HASH');result[name]=b
    require(sha(result[SOURCE_PATHS[-1]])==RUNTIME_SHA, 'RUNTIME_HASH')
    return result


