def validate_input_successor(value):
    require(type(value) is dict and len(value) == 13 and all(type(key) is str for key in value) and
            set(value) == set(P0_CURRENT_CONTRACT) and
            all(type(value[key]) is type(wanted) and value[key] == wanted
                for key, wanted in P0_CURRENT_CONTRACT.items()), 'INPUT_SUCCESSOR')
    return dict(value)


def input_selection(input_successor=None):
    if input_successor is None:
        return INPUTS_SHA, BASE_SHA
    selected = validate_input_successor(input_successor)
    return selected['inputs_sha256'], selected['packages_sha256']


def validate_selection(value):
    fields={'schema_version','purpose','phase','source_commit','sources','tool_profile_sha256','native_inputs_sha256',
            'builder_packages_sha256','image_id','image_config_sha256','native_handoff_sha256','nonce'}
    require(type(value) is dict and all(type(key) is str for key in value), 'SELECTION_SCHEMA')
    current = 'input_successor' in value
    if current: fields |= {'input_successor', 'tool_profile_lineage'}
    require(set(value)==fields and type(value['schema_version']) is int and value['schema_version']==1,
            'SELECTION_SCHEMA')
    selected = validate_input_successor(value['input_successor']) if current else None
    if current:
        require(type(value['phase']) is str and value['phase'] == 'preflight' and
                all(type(value[key]) is str for key in ('native_inputs_sha256', 'builder_packages_sha256', 'tool_profile_sha256')) and
                type(value['tool_profile_lineage']) is str and
                value['tool_profile_lineage'] == TOOL_PROFILE_LINEAGE, 'PROFILE_LINEAGE')
    require(value['purpose']=='native-arm-synthetic-installer' and value['phase'] in ('preflight','matrix'), 'SELECTION_SCOPE')
    for key,n in (('source_commit',40),('image_config_sha256',64),('native_handoff_sha256',64),('nonce',32)):
        require(type(value[key]) is str and len(value[key])==n and all(c in '0123456789abcdef' for c in value[key]), 'SELECTION_PIN')
    require(type(value['image_id']) is str and len(value['image_id'])==71 and value['image_id'].startswith('sha256:') and
            all(c in '0123456789abcdef' for c in value['image_id'][7:]), 'IMAGE_PIN')
    inputs_sha, packages_sha = input_selection(selected)
    require(value['native_inputs_sha256']==inputs_sha and value['builder_packages_sha256']==packages_sha and
            value['tool_profile_sha256']==sha(PROFILE_BYTES), 'PROFILE_PIN')
    return value


def docker_command(selection, source, inputs, output):
    """Pure constructor; caller's captured native controller verifies/owns Docker."""
    validate_selection(selection)
    require(sys.platform=='linux' and os.uname().machine=='aarch64' and os.getuid()==os.geteuid()!=0 and os.getgid()==os.getegid()!=0,
            'NATIVE_HOST_REQUIRED')
    args=['docker','run','--name','cachy-asahi-install-'+selection['nonce'],'--pull=never','--platform=linux/arm64',
          '--user',f'{os.getuid()}:{os.getgid()}','--network=none','--cgroupns=private','--cap-drop=ALL',
          '--security-opt=no-new-privileges','--security-opt=seccomp='+str(Path(inputs)/'dev-seccomp.json'),'--security-opt=apparmor='+dev_apparmor_name(),'--read-only','--pids-limit=128','--memory=2g','--cpus=2',
          '--tmpfs','/tmp:rw,nosuid,nodev,exec,size=512m,mode=1777']
    for path,target,ro in ((source,'/source',True),(inputs,'/inputs',True),(output,'/out',False)):
        require(Path(path).is_absolute() and not any(c in str(path) for c in ',\n\0'), 'BIND_PATH')
        args += ['--mount',f'type=bind,src={path},dst={target}'+(',readonly' if ro else '')]
    args += ['--env','CACHY_ASAHI_INSTALL_NONCE='+selection['nonce'],'--env','CACHY_ASAHI_INSTALL_IMAGE='+selection['image_id'],
             '--entrypoint=/usr/bin/python3',selection['image_id'],'-I','-B','/source/scripts/install/native_arm_trial.py',
             '--selection','/inputs/trial.json','--selection-sha256',sha((json.dumps(selection,sort_keys=True)+'\n').encode())]
    return args


def proc_status(end):
    check_time(end)
    with open('/proc/self/status', 'rb') as stream: data=stream.read(65537)
    require(len(data)<=65536, 'PROC_CAP');check_time(end)
    return dict(line.split(':',1) for line in data.decode().splitlines() if ':' in line)


def verify_environment(selection, end):
    validate_selection(selection)
    selected = selection.get('input_successor')
    inputs_sha, packages_sha = input_selection(selected)
    image_raw=read('/inputs/image.json',1024**2,end)
    require(sha(image_raw)==selection['native_handoff_sha256'], 'IMAGE_HANDOFF_HASH')
    image=strict(image_raw)
    fields = {'source_commit','image_id','inputs_sha256','packages_lock_sha256','architecture','os','Config'}
    if selected is not None:
        fields |= {'input_successor', 'tool_profile_lineage'}
        require(type(image) is dict and image.get('input_successor') == selected and
                type(image.get('tool_profile_lineage')) is str and
                image['tool_profile_lineage'] == TOOL_PROFILE_LINEAGE, 'IMAGE_SUCCESSOR')
        validate_input_successor(image['input_successor'])
    require(type(image) is dict and set(image)==fields and
            image['source_commit']==selection['source_commit'] and image['image_id']==selection['image_id'] and
            image['inputs_sha256']==inputs_sha and image['packages_lock_sha256']==packages_sha and
            image['architecture']=='arm64' and image['os']=='linux', 'IMAGE_HANDOFF_BINDING')
    config=image['Config']
    require(type(config) is dict and sha((json.dumps(config,sort_keys=True)+'\n').encode())==selection['image_config_sha256'], 'IMAGE_CONFIG_HASH')
    expected={'ArgsEscaped':False,'Cmd':[],'Entrypoint':[],'Env':['PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin'],
              'ExposedPorts':None,'Healthcheck':None,'Labels':{},'Shell':[],'StopSignal':None,'User':'alarm','Volumes':None,'WorkingDir':'/tmp'}
    canonical=dict(config)
    if canonical.get('Entrypoint')==['']:canonical['Entrypoint']=[]
    if canonical.get('Labels') is None:canonical['Labels']={}
    require(canonical==expected and type(canonical['ArgsEscaped']) is bool, 'IMAGE_CONFIG')
    require(sys.platform=='linux' and os.uname().machine=='aarch64' and os.getuid()==os.geteuid()!=0 and
            os.getgid()==os.getegid()!=0, 'NATIVE_ORDINARY_PARENT')
    require(os.environ.get('CACHY_ASAHI_INSTALL_NONCE')==selection['nonce'] and
            os.environ.get('CACHY_ASAHI_INSTALL_IMAGE')==selection['image_id'], 'CONTAINER_HANDOFF')
    status=proc_status(end)
    require(status.get('NoNewPrivs','').strip()=='1' and all(int(status[k].strip(),16)==0 for k in ('CapEff','CapPrm','CapInh','CapAmb','CapBnd')), 'OUTER_CAPS')
    packages = read('/builder-packages.lock',65536,end)
    require(sha(packages)==packages_sha, 'BUILDER_INVENTORY')
    if selected is not None:
        require(len(packages) == selected['packages_bytes'] and len(packages.splitlines()) == selected['packages'],
                'BUILDER_INVENTORY')
    profile=strict(PROFILE_BYTES)
    if selected is not None:
        require(profile['inputs_sha256'] == INPUTS_SHA and
                sha(PROFILE_BYTES) == 'b7fbd65e357e132949432fb00e765a05e3c76ea29a41d1df93413870d9fd1ed8' and
                all(not row['owner'].split()[0] in ('vim', 'vim-runtime') for row in profile['files']),
                'PROFILE_LINEAGE')
    for alias,target in profile['aliases'].items():
        check_time(end);require(str(Path(alias).resolve(strict=True))==target, 'TOOL_ALIAS')
    for row in profile['files']:
        b=read(row['path'],64*1024**2,end);require(len(b)==row['size'] and sha(b)==row['sha256'], 'TOOL_HASH')


def module(raw,path,name):
    value=types.ModuleType(name);value.__file__=str(path);exec(compile(raw,str(path),'exec'),value.__dict__);return value


def functions(value):
    result=[]
    for item in vars(value).values():
        if isinstance(item,types.FunctionType) and item.__module__==value.__name__: result.append(item)
        elif isinstance(item,type) and item.__module__==value.__name__:
            result += [f.__func__ if isinstance(f,(staticmethod,classmethod)) else f for f in vars(item).values()
                       if isinstance(f,(types.FunctionType,staticmethod,classmethod))]
    return tuple((f,f.__code__,f.__globals__,f.__closure__,
                  tuple(c.cell_contents for c in (f.__closure__ or ())),f.__defaults__,f.__kwdefaults__) for f in result)


def check_functions(bound):
    require(all(f.__code__ is code and f.__globals__ is glob and f.__closure__ is closure and
                all(c.cell_contents is value for c,value in zip(f.__closure__ or (),contents)) and
                f.__defaults__ is defaults and f.__kwdefaults__ is kwdefaults
                for f,code,glob,closure,contents,defaults,kwdefaults in bound), 'LOADED_CODE_DRIFT')


def report_budget(root,end):
    pending=[Path(root)];total=nodes=0;device=Path(root).stat().st_dev
    while pending:
        check_time(end);p=pending.pop();s=p.lstat();nodes+=1
        require(nodes<=20000 and s.st_dev==device and (stat.S_ISREG(s.st_mode) or stat.S_ISDIR(s.st_mode)), 'REPORT_SHAPE')
        if stat.S_ISDIR(s.st_mode):pending.extend(p.iterdir())
        else:total+=s.st_size;require(total<=64*1024**2, 'REPORT_CAP')


class Calls:
    """Existing stdout/stderr semantics with anchored process-group cleanup."""
    def __init__(self,end,runtime,guard,logs):
        self.end,self.rt,self.guard,self.logs=end,runtime,guard,logs;self.ordinal=0;self.cleanup=True
    def run(self,argv,**kwargs):
        self.guard();check_time(self.end,5);self.ordinal+=1;require(self.ordinal<=256,'CALL_CAP')
        require(type(argv) in (list,tuple) and argv and argv[0] in ('/usr/bin/python3','/usr/bin/gpg','/usr/bin/gpgconf','/usr/bin/unshare') and
                len(argv)<=128 and all(type(v) is str and '\0' not in v for v in argv), 'COMMAND_REFUSED')
        require(set(kwargs)<= {'capture_output','check','timeout','env','pass_fds'}, 'CALL_OPTIONS')
        seconds=kwargs.get('timeout');require(type(seconds) in (int,float) and math.isfinite(seconds) and 0<seconds<=1230,'CALL_TIME')
        deadline=min(self.end-5,time.monotonic()+seconds);process=None;selector=selectors.DefaultSelector();outputs=[bytearray(),bytearray()]
        try:
            mask=signal.pthread_sigmask(signal.SIG_BLOCK,self.rt.SIGNALS)
            try:
                parent=os.getpid()
                process=subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                    env=kwargs.get('env'),pass_fds=kwargs.get('pass_fds',()),start_new_session=True,
                    preexec_fn=lambda:self.rt._child_setup(parent,mask,deadline-time.monotonic()))
            finally: signal.pthread_sigmask(signal.SIG_SETMASK,mask)
            for index,stream in enumerate((process.stdout,process.stderr)):
                os.set_blocking(stream.fileno(),False);selector.register(stream,selectors.EVENT_READ,index)
            while selector.get_map():
                check_time(deadline)
                for key,_ in selector.select(min(.05,deadline-time.monotonic())):
                    b=os.read(key.fd,65536)
                    if not b:selector.unregister(key.fileobj)
                    else:outputs[key.data].extend(b);require(sum(map(len,outputs))<=8*1024**2,'OUTPUT_CAP')
            # Hold the original child wait identity until group cleanup starts.
            while os.waitid(os.P_PID,process.pid,os.WEXITED|os.WNOHANG|os.WNOWAIT) is None:check_time(deadline);time.sleep(.01)
        finally:
            with self.rt.defer_signals() as pending:
                try:
                    if process is not None:self.rt._cleanup(process)
                except BaseException:self.cleanup=False;raise
                finally:
                    selector.close()
                    if process is not None:
                        for stream in (process.stdout,process.stderr):stream.close()
            if pending:raise self.rt.Cancelled(pending[0])
        self.guard();check_time(self.end)
        result=subprocess.CompletedProcess(argv,process.returncode,bytes(outputs[0]),bytes(outputs[1]))
        if kwargs.get('check') and result.returncode:raise subprocess.CalledProcessError(result.returncode,argv,result.stdout,result.stderr)
        return result


def public(record):
    keys=('schema_version','status','phase','barrier','ABI','matrix','tests','failures','errors','skips','termination','owned_child_cleanup','first_failure')
    value={k:record[k] for k in keys}
    require(value['schema_version']==1 and type(value['schema_version']) is int and
            value['status'] in ('REFUSED','FAIL','PASS_NATIVE_PREFLIGHT_ONLY','PASS_NATIVE_FIXTURE_ONLY') and
            value['phase'] in ('inputs','preflight','ABI','matrix','complete') and
            all(value[k] in ('NOT_RUN','PASS') for k in ('barrier','ABI','matrix')) and value['first_failure'] in FAILURES and
            value['owned_child_cleanup'] in ('UNKNOWN','NOT_STARTED','PASS','FAIL') and type(value['termination']) is bool and
            all(type(value[k]) is int and 0<=value[k]<=26 for k in ('tests','failures','errors','skips')), 'PUBLIC_SCHEMA')
    require(value['status']!='PASS_NATIVE_PREFLIGHT_ONLY' or value['phase']=='complete' and value['barrier']=='PASS' and value['ABI']==value['matrix']=='NOT_RUN' and value['tests']==1 and value['owned_child_cleanup']=='PASS' and value['first_failure']=='NONE' and not any(value[k] for k in ('failures','errors','skips','termination')), 'PUBLIC_PASS')
    require(value['status']!='PASS_NATIVE_FIXTURE_ONLY' or value['phase']=='complete' and value['barrier']==value['ABI']==value['matrix']=='PASS' and value['tests']==26 and value['owned_child_cleanup']=='PASS' and value['first_failure']=='NONE' and not any(value[k] for k in ('failures','errors','skips','termination')), 'PUBLIC_PASS')
    if 'tool_profile_lineage' in record:
        require('input_successor' in record, 'PROFILE_LINEAGE')
    if 'input_successor' in record:
        value['input_successor'] = validate_input_successor(record['input_successor'])
        require(type(record.get('tool_profile_lineage')) is str and
                record['tool_profile_lineage'] == TOOL_PROFILE_LINEAGE, 'PROFILE_LINEAGE')
        value['tool_profile_lineage'] = TOOL_PROFILE_LINEAGE
    data=(json.dumps(value,sort_keys=True)+'\n').encode();require(len(data)<=4096,'PUBLIC_CAP');return data


def execute(selection,source,output,end,preflight_end):
    global TERMINAL_LEASE,LAST_RECORD
    selection=strict(json.dumps(selection,sort_keys=True,allow_nan=False));validate_selection(selection)
    check_time(preflight_end);require(preflight_end<=end and preflight_end-time.monotonic()<=60, 'PREFLIGHT_TIME')
    blobs=source_blobs(selection,source,preflight_end);verify_environment(selection,preflight_end)
    # No actor or CDLL has occurred before all required source/tool/profile checks.
    record=dict(schema_version=1,status='FAIL',phase='preflight',barrier='NOT_RUN',ABI='NOT_RUN',matrix='NOT_RUN',
                tests=0,failures=0,errors=0,skips=0,termination=False,owned_child_cleanup='UNKNOWN',first_failure='NONE')
    if 'input_successor' in selection:
        record.update(input_successor=validate_input_successor(selection['input_successor']),
                      tool_profile_lineage=TOOL_PROFILE_LINEAGE)
    output=Path(output);require(output.is_dir() and not output.is_symlink() and output.stat().st_uid==os.getuid() and
                                stat.S_IMODE(output.stat().st_mode)==0o700,'OUTPUT_DIRECTORY')
    worker=module(blobs[SOURCE_PATHS[0]],source/SOURCE_PATHS[0],'selected_installer');rt=worker.runtime()
    if TERMINAL_LEASE is not None:TERMINAL_LEASE.close();TERMINAL_LEASE=None
    evidence=worker.Evidence(output);evidence.save('result.json',record);TERMINAL_LEASE=evidence.duplicate();LAST_RECORD=record
    cancelled=[];temporary=None
    def cancel(n,frame):cancelled.append(n);raise rt.Cancelled(n)
    def failure(error):
        record['status']='FAIL';record['termination']=record['termination'] or bool(cancelled) or isinstance(error,rt.Cancelled)
        if record['first_failure']=='NONE':
            code=str(error) if type(error) is ValueError else None
            record['first_failure']='CANCELLED' if record['termination'] else code if code in FAILURES else 'IO_OR_TOOL_FAILED' if isinstance(error,OSError) else 'INTERNAL'
        (evidence if evidence.fd is not None else TERMINAL_LEASE).revoke(record)
    try:
        with rt._handlers(cancel):
            temporary=tempfile.TemporaryDirectory(prefix='caa-arm-trial-');tree=Path(temporary.name);tree.chmod(0o700)
            for name,b in blobs.items():
                p=tree/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(b);p.chmod(0o400)
            tests=module(blobs[SOURCE_PATHS[1]],tree/SOURCE_PATHS[1],'selected_native_tests')
            tests.REVIEWED_WORKER_SHA256=selection['sources'][SOURCE_PATHS[0]]['sha256']
            tests.LIBALPM_SHA256=worker.NATIVE_LIBRARY_SHA;tests.FIXTURE_SELECTION_SHA256=sha((json.dumps(selection,sort_keys=True)+'\n').encode())
            tests.ARTIFACTS=output/'attempts'
            bound=functions(tests)+functions(worker)+functions(rt)
            expected_library=worker.NATIVE_LIBRARY_SHA;expected_profile=worker.NATIVE_PROFILE_SHA
            require(expected_profile==selection['tool_profile_sha256'] and expected_library==next(r['sha256'] for r in strict(PROFILE_BYTES)['files'] if r['path']=='/usr/lib/libalpm.so.16.0.1'), 'ENGINE_PROFILE_BINDING')
            def guard():
                check_functions(bound);source_blobs(selection,source,end)
                require(functions(tests)+functions(worker)+functions(rt)==bound, 'LOADED_BINDING_DRIFT')
                require(sha(PROFILE_BYTES)==expected_profile, 'TOOL_PROFILE_DRIFT')
                report_budget(output,end)
                require(worker.NATIVE_LIBRARY_SHA==expected_library and worker.NATIVE_PROFILE_SHA==expected_profile and
                        worker.RUNTIME_SHA==RUNTIME_SHA and worker.FLAGS==(1<<7)|(1<<10) and
                        worker.LIBRARY==Path('/usr/lib/libalpm.so.16.0.1') and
                        tests.REVIEWED_WORKER_SHA256==selection['sources'][SOURCE_PATHS[0]]['sha256'] and
                        tests.LIBALPM_SHA256==worker.NATIVE_LIBRARY_SHA and tests.FIXTURE_SELECTION_SHA256==sha((json.dumps(selection,sort_keys=True)+'\n').encode()),'TEST_BINDING_DRIFT')
            calls=Calls(preflight_end,rt,guard,output)
            stream=io.StringIO()
            with contextlib.ExitStack() as stack:
                from unittest.mock import patch
                stack.enter_context(patch.object(subprocess,'run',calls.run))
                result=unittest.TextTestRunner(stream=stream,verbosity=2).run(unittest.TestSuite([tests.BarrierTests(SELECTED['BarrierTests'][0])]))
            evidence.write('preflight.log',stream.getvalue().encode(),exclusive=True)
            require(result.wasSuccessful() and result.testsRun==1 and not result.skipped and calls.ordinal==1 and calls.cleanup,'BARRIER_FAILED');record['barrier']='PASS'
            record['tests']=1
            require(tests.BarrierTests.last_report['worker_sha256']==tests.REVIEWED_WORKER_SHA256,'BARRIER_BINDING')
            evidence.save('result.json',record);guard()
            if selection['phase']=='matrix':
                record['phase']='ABI';verify_environment(selection,end);guard()
                # ABI query must follow an independently checked complete barrier.
                import ctypes
                library=ctypes.CDLL('/usr/lib/libalpm.so.16.0.1');library.alpm_version.restype=ctypes.c_char_p
                require(library.alpm_version()==b'16.0.1','ABI_FAILED');record['ABI']='PASS';record['phase']='matrix';evidence.save('result.json',record)
                calls.end=end
                with contextlib.ExitStack() as stack:
                    stack.enter_context(patch.object(subprocess,'run',calls.run));matrix=unittest.TestSuite()
                    for cls,names in SELECTED.items():
                        for name in names:matrix.addTest(getattr(tests,cls)(name))
                    result=unittest.TextTestRunner(stream=stream,verbosity=2).run(matrix)
                record.update(tests=result.testsRun,failures=len(result.failures),errors=len(result.errors),skips=len(result.skipped))
                evidence.write('matrix.log',stream.getvalue().encode(),exclusive=True)
                require(result.wasSuccessful() and result.testsRun==26 and not result.skipped,'MATRIX_FAILED');record['matrix']='PASS'
            record['owned_child_cleanup']='PASS' if calls.cleanup else 'FAIL'
            temporary.cleanup();temporary=None;guard();verify_environment(selection,end);check_time(end);require(not cancelled,'TERMINATED')
            record.update(status='PASS_NATIVE_PREFLIGHT_ONLY' if selection['phase']=='preflight' else 'PASS_NATIVE_FIXTURE_ONLY',phase='complete');evidence.save('result.json',record)
        require(not cancelled,'TERMINATED');check_time(end);evidence.check();return record
    except BaseException as error:
        record.update(owned_child_cleanup=('PASS' if calls.cleanup else 'FAIL') if 'calls' in locals() and calls.ordinal else 'NOT_STARTED')
        failure(error);return record
    finally:
        try:
            errors=[]
            with rt.defer_signals() as pending:
                if temporary is not None:
                    try:temporary.cleanup()
                    except BaseException as error:errors.append(error)
                try:
                    # Promotion replaced result.json: refresh the loan to its
                    # newest owned inode before closing the primary descriptor.
                    old=TERMINAL_LEASE;TERMINAL_LEASE=evidence.duplicate();old.close()
                    evidence.close()
                except BaseException as error:errors.append(error)
            if pending:raise rt.Cancelled(pending[0])
            if errors:raise errors[0]
        except BaseException as error:failure(error)


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--selection',type=Path,required=True)
    parser.add_argument('--selection-sha256',required=True);args=parser.parse_args();start=time.monotonic()
    accepted_successor = None
    try:
        require(args.selection==Path('/inputs/trial.json'),'SELECTION_PATH')
        raw=read(args.selection,1024**2,start+60);require(sha(raw)==args.selection_sha256,'SELECTION_HASH')
        selection=validate_selection(strict(raw));require(raw==(json.dumps(selection,sort_keys=True)+'\n').encode(),'SELECTION_CANONICAL')
        if 'input_successor' in selection:
            accepted_successor = validate_input_successor(selection['input_successor'])
        end=start+(60 if selection['phase']=='preflight' else 1800)
        record=execute(selection,Path('/source'),Path('/out'),end,start+60);sys.stdout.buffer.write(public(record));sys.stdout.buffer.flush()
        return int(record['status'] not in ('PASS_NATIVE_PREFLIGHT_ONLY','PASS_NATIVE_FIXTURE_ONLY'))
    except BaseException:
        if LAST_RECORD is not None:
            record=LAST_RECORD;record['status']='FAIL'
            if record['first_failure']=='NONE':record['first_failure']='PUBLICATION_FAILED'
            if TERMINAL_LEASE is not None:TERMINAL_LEASE.revoke(record)
        else:record=dict(schema_version=1,status='REFUSED',phase='inputs',barrier='NOT_RUN',ABI='NOT_RUN',matrix='NOT_RUN',tests=0,failures=0,errors=0,skips=0,termination=False,owned_child_cleanup='NOT_STARTED',first_failure='INPUT_REFUSED')
        if accepted_successor is not None:
            record.update(input_successor=accepted_successor, tool_profile_lineage=TOOL_PROFILE_LINEAGE)
        sys.stdout.buffer.write(public(record));sys.stdout.buffer.flush();return 2


